/* ================= FILTROS (modelo Trello) ================= */
const F0=()=>({q:'',membros:new Set(),prazo:new Set(),etq:new Set(),estado:'todos',ativ:'qualquer',vinc:new Set(),prio:new Set(),extra:new Set(),modo:'qualquer',ocultar:true});
let F=F0();
const filtroAtivo=()=>F.q||F.membros.size||F.prazo.size||F.etq.size||F.estado!=='todos'||F.ativ!=='qualquer'||F.vinc.size||F.prio.size||F.extra.size;
function casa(c){ if(c.arq) return false;
  const tests=[];
  if(F.q){ const q=F.q.toLowerCase(); tests.push(()=>(c.t+' '+c.desc+' '+c.com.map(x=>x[1]).join(' ')).toLowerCase().includes(q)); }
  if(F.membros.size) tests.push(()=>[...F.membros].some(k=>k==='nenhum'?c.m.length===0:k==='eu'?c.m.includes(EU):c.m.includes(k)));
  if(F.etq.size) tests.push(()=>[...F.etq].some(k=>k==='nenhuma'?c.lab.length===0:c.lab.includes(k)));
  if(F.prazo.size) tests.push(()=>[...F.prazo].some(k=>{const n=nDias(c);return k==='sem'?!c.prazo:k==='atrasados'?(c.prazo&&c.col!=='feito'&&n<0):k==='24h'?(c.prazo&&c.col!=='feito'&&n>=0&&n<=1):k==='semana'?(c.prazo&&c.col!=='feito'&&n>=0&&n<=7):k==='mes'?(c.prazo&&c.col!=='feito'&&n>=0&&n<=30):false;}));
  if(F.estado!=='todos') tests.push(()=>F.estado==='feitos'?c.col==='feito':c.col!=='feito');
  if(F.ativ!=='qualquer') tests.push(()=>{const dias=(Date.now()-c.ativ)/864e5;return F.ativ==='1s'?dias<=7:F.ativ==='2s'?dias<=14:F.ativ==='4s'?dias<=28:dias>28;});
  if(F.vinc.size) tests.push(()=>[...F.vinc].some(k=>c.vinc.some(v=>v.tipo===k)));
  if(F.prio.size) tests.push(()=>F.prio.has((c.campos||{}).prio));
  if(F.extra.size) tests.push(()=>[...F.extra].some(k=>k==='local'?!!c.local:k==='naolido'?naoLido(c):k==='semlocal'?!c.local:false));
  if(!tests.length) return true;
  return F.modo==='todos'?tests.every(f=>f()):tests.every(f=>f()); // grupos combinam com E; dentro do grupo, "qualquer" (OU)
}
function resumoFiltros(){ const ch=[];
  if(F.q) ch.push(['q',`“${F.q}”`]);
  F.membros.forEach(k=>ch.push(['membros:'+k,k==='nenhum'?'Sem membros':k==='eu'?'Atribuídos a mim':PESSOAS[k][0]]));
  F.etq.forEach(k=>ch.push(['etq:'+k,k==='nenhuma'?'Sem etiquetas':lab(k).n]));
  F.prazo.forEach(k=>ch.push(['prazo:'+k,{sem:'Sem prazo',atrasados:'Atrasados','24h':'Vence em 24 h',semana:'Vence na semana',mes:'Vence no mês'}[k]]));
  if(F.estado!=='todos') ch.push(['estado',F.estado==='feitos'?'Concluídos':'Em aberto']);
  if(F.ativ!=='qualquer') ch.push(['ativ',{'1s':'Ativo na última semana','2s':'Ativo em 2 semanas','4s':'Ativo em 4 semanas',sem:'Sem atividade há mais de 4 semanas'}[F.ativ]]);
  F.vinc.forEach(k=>ch.push(['vinc:'+k,'Vínculo: '+ROTAS[k][0]]));
  F.prio.forEach(k=>ch.push(['prio:'+k,'Prioridade '+k]));
  F.extra.forEach(k=>ch.push(['extra:'+k,{local:'Com local',naolido:'Não lidos por mim',semlocal:'Sem local'}[k]]));
  return ch; }
function tiraFiltro(k){ const [a,b]=k.split(':'); if(a==='q') F.q=''; else if(a==='estado') F.estado='todos'; else if(a==='ativ') F.ativ='qualquer'; else { const v=a==='etq'&&b!=='nenhuma'?+b:b; F[a==='membros'?'membros':a==='etq'?'etq':a==='prazo'?'prazo':a==='vinc'?'vinc':a==='extra'?'extra':'prio'].delete(v); } render(); }
function renderFiltros(){ const ch=resumoFiltros(), box=$('#filtros'); const vis=cartoes.filter(c=>!c.arq), n=vis.filter(casa).length;
  $('#nFiltro').textContent=ch.length; $('#nFiltro').classList.toggle('hide',!ch.length); $('#bFiltro').classList.toggle('on',!!ch.length);
  box.innerHTML=ch.length?`<span class="mono" style="color:var(--lane-mut)">${n} de ${vis.length} cartões</span>${ch.map(([k,t])=>`<span class="fchip">${t}<button data-fx="${k}" aria-label="Remover filtro">${ic('x')}</button></span>`).join('')}<button class="btn" id="limpaF">Limpar tudo</button>`:'';
  box.querySelectorAll('[data-fx]').forEach(b=>b.onclick=()=>tiraFiltro(b.dataset.fx)); $('#limpaF')&&($('#limpaF').onclick=()=>{F=F0();render();}); }
