function liveVal(tipo,ref){ const L=EV.lotes; switch(tipo){
  case 'ingresso':{const l=L.find(x=>x.id===ref)||L[0];return {t:l.n,v:`${l.v} de ${l.t}`,s:`${Math.round(l.v/l.t*100)}% vendido · ${brl(l.p)} cada`,w:l.v/l.t*100};}
  case 'cupom':{const c=EV.cupons[0];return {t:'Cupom '+c.c,v:`${c.u} de ${c.m} usos`,s:'Restam '+(c.m-c.u),w:c.u/c.m*100};}
  case 'participantes':return {t:'Participantes',v:EV.inscritos+' inscritos',s:'Lista completa e exportação',w:100};
  case 'checkin':return {t:'Check-in',v:`${EV.checkin} de ${EV.ingressos}`,s:dEvento()>0?`Abre em ${dEvento()} dias`:'Aberto',w:EV.checkin/EV.ingressos*100};
  case 'orcamento':return {t:'Orçamento do evento',v:SEMFIN?'—':`${Math.round(EV.orc.gasto/EV.orc.prev*100)}% usado`,s:SEMFIN?'Sem permissão financeira':`${brl(EV.orc.gasto)} de ${brl(EV.orc.prev)}`,w:SEMFIN?0:EV.orc.gasto/EV.orc.prev*100};
  case 'financeiro':return {t:'Vendas pagas',v:brl(EV.vendas),s:SEMFIN?'Sem permissão financeira':'Fonte única: produtor_vendas_pagas',w:100};
  case 'parceiro':return {t:'Parceiros e fornecedores',v:EV.parceiros+' cadastrados',s:'Contratos e comprovantes',w:100};
  case 'equipe':return {t:'Equipe',v:'4 membros ativos',s:'Permissão por ferramenta',w:100};
  case 'mapa':return {t:'Lugar marcado',v:'3 setores',s:'Mapa publicado',w:100};
  case 'divulgacao':return {t:'Divulgação',v:'2 campanhas ativas',s:'UTM e pixels',w:100};
  case 'crm':return {t:'CRM',v:'128 contatos',s:'Funil ligado às vendas',w:100};
  default:return {t:ROTAS[tipo][0],v:'—',s:'',w:0};}}
function renderDados(){ const l1=EV.lotes[0], p=Math.round(l1.v/l1.t*100); const K=[
  ['chart','Vendas pagas',brl(EV.vendas),null,'financeiro'],['ingresso'&&'clip','Ingressos',String(EV.ingressos),null,'participantes'],
  ['tag',l1.n,`${p}% vendido`,p,'ingresso'],['check','Orçamento',SEMFIN?'—':Math.round(EV.orc.gasto/EV.orc.prev*100)+'% usado',SEMFIN?null:EV.orc.gasto/EV.orc.prev*100,'orcamento'],['user','Check-in',`${EV.checkin}/${EV.ingressos}`,EV.checkin/EV.ingressos*100,'checkin']];
  $('#dados').innerHTML=K.map(([i,r,v,w,t])=>`<button class="kpi" data-go="${t}" title="Abrir ${ROTAS[t][0]}"><small><span class="vivo"></span>${r}</small><b>${v}</b>${w!=null?`<i><u style="--w:${Math.min(100,w)}%"></u></i>`:''}<span class="go">${ic('ext')}</span></button>`).join('')+`<span class="mono" style="align-self:center;color:var(--lane-mut);margin-left:4px">dados ao vivo do evento</span>`;
  $('#dados').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>irPara(b.dataset.go)); }
function irPara(t){ toast(`Abre <b>${ROTAS[t][0]}</b> do evento (<span class="mono">${href(t)}</span>). No app, é navegação direta.`); }
/* ================= INSIGHT DO EVO ================= */
function insights(){ const ab=cartoes.filter(c=>!c.arq&&c.col!=='feito'); const atr=ab.filter(c=>c.prazo&&nDias(c)<0), sem=ab.filter(c=>!c.m.length), prox=ab.filter(c=>c.prazo&&nDias(c)>=0&&nDias(c)<=2);
  const partes=[]; if(atr.length) partes.push(`<b>${atr.length}</b> atrasado${atr.length>1?'s':''}`); if(sem.length) partes.push(`<b>${sem.length}</b> sem responsável`); if(prox.length) partes.push(`<b>${prox.length}</b> vence${prox.length>1?'m':''} em até 2 dias`);
  $('#insight').innerHTML=partes.length?`${orb()}<span><b>Evo notou:</b> ${partes.join(' · ')}.</span><button class="btn" id="vIns">Ver quais</button><button class="btn v" id="aIns">Pedir plano ao Evo</button>`:`${orb()}<span><b>Evo:</b> tudo no ritmo para o dia 14. Nada pede atenção agora.</span><button class="btn" id="aIns">Perguntar ao Evo</button>`;
  $('#vIns')&&($('#vIns').onclick=()=>{ F=F0(); if(atr.length) F.prazo.add('atrasados'); else if(sem.length) F.membros.add('nenhum'); else F.prazo.add('24h'); render(); });
  $('#aIns').onclick=()=>{ abrirEvo(); evoPerguntar(partes.length?'O que está em risco?':'Resumir o quadro'); }; }
