function ordena(lista,modo){ const k={prazo:c=>c.prazo?+c.prazo:9e15,nome:c=>c.t.toLowerCase(),criacao:c=>c.id}[modo]; return lista.sort((x,y)=>k(x)>k(y)?1:-1); }
