  T('Membros'); tog(F.membros,'m','<span>Sem membros</span>','nenhum'); tog(F.membros,'m','<span>Atribuídos a mim</span>','eu'); Object.entries(PESSOAS).filter(([k])=>k!=='evo').forEach(([k,[n]])=>tog(F.membros,'m',`${av(k,true)}<span>${n}</span>`,k));
  T('Prazo'); [['sem','Sem prazo'],['atrasados','Atrasados'],['24h','Vence nas próximas 24 horas'],['semana','Vence na próxima semana'],['mes','Vence no próximo mês']].forEach(([k,t])=>tog(F.prazo,'p',`<span>${t}</span>`,k));
