  if(pag==='etq'){ gc.innerHTML=LAB.map(l=>`<div class="row"><span class="lb" style="--t:${l.c};flex:1">${l.n}</span><button class="btn" data-re="${l.id}">Renomear</button><button class="btn d" data-de="${l.id}">${ic('lixo')}</button></div>`).join('')+`<button class="btn v" id="ne">${ic('plus')}Nova etiqueta</button>`;
    gc.querySelectorAll('[data-re]').forEach(b=>b.onclick=()=>{ const l=lab(+b.dataset.re),n=prompt('Novo nome',l.n); if(n){ l.n=n; render(); menuQuadro('etq'); } }); gc.querySelectorAll('[data-de]').forEach(b=>b.onclick=()=>{ const id=+b.dataset.de; LAB=LAB.filter(l=>l.id!==id); cartoes.forEach(c=>c.lab=c.lab.filter(x=>x!==id)); render(); menuQuadro('etq'); }); $('#ne').onclick=()=>{ const n=prompt('Nome da etiqueta'); if(n){ LAB.push({id:Date.now(),n,c:CORES[LAB.length%CORES.length]}); menuQuadro('etq'); } }; }
  if(pag==='fundo'){ gc.innerHTML=`<div class="sec-t">Aparência</div><div class="row"><button class="btn ${document.documentElement.dataset.skin==='claro'?'on':''}" data-sk="claro">Claro</button><button class="btn ${document.documentElement.dataset.skin==='escuro'?'on':''}" data-sk="escuro">Escuro</button></div><div class="sec-t">Fundo do quadro</div><div class="row"><button class="btn" data-fd="padrao">Branco</button><button class="btn" data-fd="marinho">Marinho</button><button class="btn" data-fd="violeta">Violeta</button></div><div class="nota">Branco, marinho e violeta são as cores da marca. O ingresso mantém a superfície clara ou escura do tema.</div>`;
    gc.querySelectorAll('[data-sk]').forEach(b=>b.onclick=()=>setSkin(b.dataset.sk)); gc.querySelectorAll('[data-fd]').forEach(b=>b.onclick=()=>{ document.documentElement.dataset.fundo=b.dataset.fd; }); }
  if(pag==='auto') menuAuto(gc);
