let evoCred=18,evoMsgs=[],evoAberto=false,evoAba='evo';
function abrirEvo(){ $('#evo').classList.add('on'); $('#evoVeu').classList.add('on'); evoAberto=true; $('#evoFab').classList.remove('dica'); if(!evoMsgs.length) evoMsgs.push({de:'evo',h:`Oi, eu sou o Evo. Vejo o quadro e os dados do <b>${EV.nome}</b> (vendas, lotes, cupons, check-in e orçamento).<br>Eu proponho; <b>nada é gravado sem o seu clique</b>, e dinheiro eu só leio.`}); evoRender(); }
