    if(k==='men'){ const c=cartoes.find(x=>x.id===5); const m={q:'caio',t:`@${nome(EU).toLowerCase()} consegue ver o roteiro hoje?`,ts:Date.now(),ent:{},lido:{}}; c.com.unshift(m); if(!c.m.includes(EU)) c.m.push(EU); destinatarios(c,m).forEach(r=>{ if(ONLINE[r]) m.ent[r]=Date.now(); }); notificar(EU,'mencao',c,`Caio mencionou você em “${c.t}”: consegue ver o roteiro hoje?`,'caio'); render(); }
