let userLoc=null,mapaObj=null; const enc=encodeURIComponent;
const destStr=l=>l.lat!=null?`${l.lat},${l.lon}`:l.txt, orgStr=()=>userLoc?`${userLoc.lat},${userLoc.lon}`:null;
