/* ---- colunas: nova, arrastar e teclado ---- */
const COR_COL=['#5b8bd0','#c4638a','#4f9d7e','#c29a3c','#8570d0','#3f9aa0'];
function colAnd(){ return COLS.find(c=>c.id==='andamento')||COLS[0]; }
function novaColuna(pos,nomeDado){ const titulo=nomeDado!=null?nomeDado:prompt('Nome da nova coluna'); if(!titulo||!titulo.trim()) return null; const c={id:'c'+Date.now()+Math.floor(Math.random()*99),nome:titulo.trim().slice(0,40),c:COR_COL[COLS.length%COR_COL.length],wip:null}; COLS.splice(pos==null?COLS.length:pos,0,c); logA(`<b>${nome(EU)}</b> criou a coluna <b>${esc(c.nome)}</b>`,EU); render(); toast(`Coluna “${esc(c.nome)}” criada`); return c; }
function moveColuna(id,para){ const de=COLS.findIndex(c=>c.id===id); para=Math.max(0,Math.min(COLS.length-1,para)); if(de<0||de===para) return false; const [c]=COLS.splice(de,1); COLS.splice(para,0,c); logA(`<b>${nome(EU)}</b> moveu a coluna <b>${esc(c.nome)}</b> para a posição ${para+1}`,EU); render(); live(`Coluna ${c.nome} movida para a posição ${para+1} de ${COLS.length}.`); return true; }
function ligarPuxa(b){ const id=b.dataset.puxa;
  b.addEventListener('keydown',e=>{ const i=COLS.findIndex(c=>c.id===id); if(e.key==='ArrowLeft'||e.key==='ArrowRight'){ e.preventDefault(); if(moveColuna(id,i+(e.key==='ArrowLeft'?-1:1))) setTimeout(()=>document.querySelector(`[data-puxa="${id}"]`)?.focus(),30); } });
  b.addEventListener('pointerdown',e=>{ if(e.button>0) return; e.preventDefault(); const mesa=$('#mesa'),lanes=[...mesa.querySelectorAll('.lane:not(.add-col)')],src=lanes.find(l=>l.dataset.col===id); if(!src) return; src.classList.add('arrastada'); let alvo=COLS.findIndex(c=>c.id===id);
    const ind=document.createElement('div'); ind.className='ind-col'; mesa.append(ind);
    const move=ev=>{ let idx=lanes.findIndex(l=>{const r=l.getBoundingClientRect();return ev.clientX<r.left+r.width/2}); if(idx<0) idx=lanes.length; alvo=idx; const mr=mesa.getBoundingClientRect(),r=(idx<lanes.length?lanes[idx].getBoundingClientRect().left:lanes[lanes.length-1].getBoundingClientRect().right); ind.style.left=(r-mr.left+mesa.scrollLeft-1)+'px'; ind.style.top='0'; ind.style.height=mesa.scrollHeight+'px'; };
    const up=()=>{ removeEventListener('pointermove',move); removeEventListener('pointerup',up); removeEventListener('pointercancel',up); src.classList.remove('arrastada'); ind.remove(); const de=COLS.findIndex(c=>c.id===id); let para=alvo; if(para>de) para--; if(para!==de) moveColuna(id,para); };
    addEventListener('pointermove',move); addEventListener('pointerup',up); addEventListener('pointercancel',up); move(e); }); }

